"""Line-number-insensitive harvest diff: groups by module.qualname, compares sorted multisets."""
import json, sys
from collections import defaultdict
def group(d):
  g = defaultdict(list)
  for k, names in d.items(): g[k.rsplit(':', 1)[0]].append(tuple(names))
  return {k: sorted(v) for k, v in g.items()}
pre, post = group(json.load(open(sys.argv[1]))), group(json.load(open(sys.argv[2])))
real = [k for k in sorted(set(pre) | set(post)) if pre.get(k, []) != post.get(k, [])]
if not real: print("DELTA: empty")
for k in real:
  a, b = pre.get(k, []), post.get(k, [])
  print(f"DELTA {k}: pre-only={[sorted(t) for t in a if t not in b]} post-only={[sorted(t) for t in b if t not in a]}")
